import { updateTag } from "next/cache";

export interface RebakeResult {
  rebakedAt: string;
}

/**
 * Expires the `landing-shell` cache entry immediately (read-your-own-writes),
 * so the visitor who pressed the button sees the new bake in the same
 * round-trip. `revalidateTag` would refresh it lazily in the background;
 * for a demo, "watch it change right now" is the whole point.
 */
// biome-ignore lint/suspicious/useAwait: server actions must be async functions, even when nothing awaits
export async function rebakeShell(): Promise<RebakeResult> {
  updateTag("landing-shell");
  return { rebakedAt: new Date().toISOString() };
}
import { cacheLife, cacheTag } from "next/cache";

export interface Bake {
  bakedAt: string;
  id: string;
}

/**
 * The page's own cache entry. Runs once, lands in the static shell, and is
 * served as-is until someone presses the re-bake button (updateTag) or the
 * cache lifetime runs out. The random id exists so a re-bake is undeniable —
 * timestamps invite squinting, fingerprints don't.
 *
 * Six hex characters, so the fingerprint IS a CSS color — the swatch beside
 * it renders the literal value, nothing derived, nothing truncated.
 *
 * The hero and the shell demo both read this, so they can never disagree.
 */
// biome-ignore lint/suspicious/useAwait: `use cache` only works on async functions, even when nothing awaits
export async function getBake(): Promise<Bake> {
  "use cache";
  cacheTag("landing-shell");
  cacheLife("days");

  return {
    bakedAt: new Date().toISOString(),
    id: crypto.randomUUID().slice(0, 6),
  };
}

