 */
function StableSlot({
  className,
  value,
  variants,
}: {
  className?: string;
  value: string;
  variants: readonly string[];
}) {
  return (
    <span className={cn("grid", className)}>
      {variants.map((variant) => (
        <span
          aria-hidden="true"
          className="invisible [grid-area:1/1]"
          key={variant}
        >
          {variant}
        </span>
      ))}
      <span className="[grid-area:1/1]">{value}</span>
    </span>
  );
}

